from collections import deque
R=C=16
seen=set(); comps=[]
for r in range(R):
    for c in range(C):
        if grid[r][c]!=7 and (r,c) not in seen:
            q=[(r,c)];seen.add((r,c)); cells=[]
            while q:
                x,y=q.pop(); cells.append((x,y))
                for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
                    a,b=x+dx,y+dy
                    if 0<=a<R and 0<=b<C and grid[a][b]!=7 and (a,b) not in seen:
                        seen.add((a,b));q.append((a,b))
            comps.append(cells)
[(len(c), (min(x for x,y in c), min(y for x,y in c), max(x for x,y in c), max(y for x,y in c)), sorted(set(grid[x][y] for x,y in c)), [(x,y,grid[x][y]) for x,y in c if grid[x][y] not in (0,3)]) for c in comps]

clue={5,6,8}
out=[row[:] for row in grid]
cleared=[]
for comp in comps:
    colors={grid[r][c] for r,c in comp if grid[r][c] not in (0,7,3)}
    if clue <= colors:
        cleared.append((len(comp), (min(r for r,c in comp),min(c for r,c in comp),max(r for r,c in comp),max(c for r,c in comp)), colors))
        for r,c in comp: out[r][c]=7
cleared, '\n'.join(' '.join(map(str,row)) for row in out)
